from pathlib import Path
import json,dash
import dash_bootstrap_components as dbc
from dash import html,dcc,Input,Output,callback
import plotly.graph_objects as go
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/diagnosticos/explicaciones_cpu.json').read_text())
P=json.loads((ROOT/'data/diagnosticos/planificacion_potencia.json').read_text())
dash.register_page(__name__,path='/calidad-explicaciones',name='Comprobar explicaciones')
layout=html.Div([html.Span('EVIDENCIA CPU · SIN REENTRENAR',className='eyebrow'),html.H1('Poner a prueba lo que destaca el mapa'),html.P('Si una zona influye en la puntuación, ocultarla debería cambiarla. Comparamos el orden de las zonas destacadas con diez órdenes aleatorios.',className='lead'),dbc.Alert(D['alcance'],color='info'),html.Label('Ejemplo histológico',htmlFor='quality-case'),dcc.Dropdown(id='quality-case',options=[{'label':'Caso '+r['caso']+' · '+r['clase_referencia'],'value':r['caso']} for r in D['casos']],value='01',clearable=False),html.Div(id='quality-details'),dbc.Row([dbc.Col(dcc.Graph(id='quality-deletion'),xs=12,md=6),dbc.Col(dcc.Graph(id='quality-insertion'),xs=12,md=6)]),html.P('Ejes: fracción de bloques de 16×16 modificados y puntuación de la clase originalmente elegida. La línea discontinua es el promedio de diez órdenes aleatorios, no un intervalo de confianza.'),html.P('La evaluación usa el mismo relleno que el mapa: color medio del recorte. Esta afinidad limita la prueba; falta comprobar otros tipos de intervención y datos independientes.',className='notice'),html.A('Método y tabla en el libro',href='/libro/22_calidad_explicaciones.html',className='button'),html.H2('¿Bastan diez semillas?'),html.P('El mínimo de la guía no garantiza potencia suficiente. Estos escenarios muestran cómo cambia el tamaño aproximado según el efecto que se quiere detectar; todavía no fijan el protocolo final.'),html.Table([html.Thead(html.Tr([html.Th(t) for t in ['Variante','DE diferencias','MDE con n=10','n para Δ=0,02']])),html.Tbody([html.Tr([html.Td(r['variante']),html.Td(f"{r['sd_diferencias']:.4f}"),html.Td(f"{r['mde90_n10']:.4f}"),html.Td(r['escenarios'][1]['n_con_piso_guia'])]) for r in P['filas']])]),html.P(P['alcance'],className='note'),html.A('Ver supuestos y escenarios',href='/libro/23_planificacion_potencia.html',className='button secondary')])
@callback(Output('quality-details','children'),Output('quality-deletion','figure'),Output('quality-insertion','figure'),Input('quality-case','value'))
def show(case):
 r=next(x for x in D['casos'] if x['caso']==case)
 figures=[]
 for name,title in [('eliminacion','Ocultar regiones: menor área es favorable'),('insercion','Recuperar regiones: mayor área es favorable')]:
  f=go.Figure();f.add_scatter(x=r['fracciones'],y=r[name],name='Orden del mapa',mode='lines+markers',line={'color':'#147d79'});f.add_scatter(x=r['fracciones'],y=r[name+'_aleatoria_media'],name='Orden aleatorio · media de 10',mode='lines',line={'color':'#72518f','dash':'dash'});f.update_layout(template='plotly_white',title=title,xaxis_title='Fracción de bloques modificados',yaxis_title='Puntuación de la clase objetivo',yaxis_range=[0,1],legend={'orientation':'h'},height=430);figures.append(f)
 details=dbc.Row([dbc.Col(html.Img(src='/ejemplo-png/'+case,alt='Recorte histológico del caso '+case,style={'width':'180px','maxWidth':'100%'}),xs=12,md=3),dbc.Col([html.H2('Caso '+case),html.P('Referencia: '+r['clase_referencia']+' · Clase analizada: '+r['clase_objetivo']),html.P(f"Δ AUC eliminación: {r['auc_eliminacion']-r['auc_eliminacion_aleatoria']:.4f} · Δ AUC inserción: {r['auc_insercion']-r['auc_insercion_aleatoria']:.4f}"),html.P(f"Correlación del mapa rotado y realineado: {r['correlacion_mapa_rotado']:.8f}. Esta simetría es parte del diseño; no prueba robustez general.")],xs=12,md=9)])
 return details,*figures
